	string changes;
public:
    void store_rev_time(int t) { rev_time = t; }
    void store_changes(const string& c) { changes = c; }

    void output() const {
        Film::output();
        cout << "Revised time: " << rev_time <<" mins"<< endl;
        cout << "Changes: " << changes << endl;
    }
};
class ForeignFilm :public Film
